import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Button · Lazer DS Starter Kit
 * Figma: Components page, Button set. Style x State.
 * Every value comes from tier 3 tokens (--component-button-*). Retone 01 Primitives, not this file.
 */
type ButtonStyle = "primary" | "secondary" | "destructive"
type ButtonState = "default" | "pending" | "success" | "error"

const styles: Record<ButtonStyle, string> = {
  primary:
    "bg-[var(--component-button-primary-background)] text-[var(--component-button-primary-label)] border-[var(--component-button-primary-border)] hover:bg-[var(--component-button-primary-background-hover)]",
  secondary:
    "bg-[var(--component-button-secondary-background)] text-[var(--component-button-secondary-label)] border-[var(--component-button-secondary-border)] hover:bg-[var(--component-button-secondary-background-hover)]",
  destructive:
    "bg-[var(--component-button-destructive-background)] text-[var(--component-button-destructive-label)] border-[var(--component-button-destructive-border)] hover:bg-[var(--component-button-destructive-background-hover)]",
}
const settled: Record<Exclude<ButtonState, "default" | "pending">, string> = {
  success:
    "bg-[var(--component-button-success-background)] text-[var(--component-button-success-label)] border-[var(--component-button-success-border)] hover:bg-[var(--component-button-success-background)]",
  error:
    "bg-[var(--component-button-error-background)] text-[var(--component-button-error-label)] border-[var(--component-button-error-border)] hover:bg-[var(--component-button-error-background)]",
}

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Figma property Style */
  variant?: ButtonStyle
  /** Figma property State. Hover and Disabled come from the browser. */
  state?: ButtonState
  leadingIcon?: React.ReactNode
  trailingIcon?: React.ReactNode
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ variant = "primary", state = "default", leadingIcon, trailingIcon, className, children, disabled, ...props }, ref) => (
    <button
      ref={ref}
      data-slot="button"
      data-variant={variant}
      data-state={state}
      disabled={disabled || state === "pending"}
      aria-busy={state === "pending" || undefined}
      className={cn(
        "lz-body-emphasis inline-flex items-center justify-center whitespace-nowrap",
        "gap-[var(--inline-sm)] px-[var(--component-button-primary-padding-inline)] py-[var(--component-button-primary-padding-block)]",
        "rounded-[var(--component-button-primary-radius)] border-[length:var(--stroke-hairline)] border-solid",
        "transition-colors duration-[var(--component-button-duration)] ease-[var(--motion-ease-standard)]",
        "outline-none focus-visible:ring-[length:var(--stroke-heavy)] focus-visible:ring-[var(--border-focus)] focus-visible:ring-offset-2",
        state === "success" || state === "error" ? settled[state] : styles[variant],
        "disabled:cursor-not-allowed disabled:bg-[var(--component-button-disabled-background)] disabled:border-[var(--component-button-disabled-background)] disabled:text-[var(--component-button-disabled-label)]",
        state === "pending" && "disabled:bg-[var(--component-button-primary-background)] disabled:text-[var(--component-button-primary-label)] disabled:cursor-progress",
        className
      )}
      {...props}
    >
      {leadingIcon ? <span className="inline-flex size-[var(--component-icon-size-md)] shrink-0 [&>svg]:size-full">{leadingIcon}</span> : null}
      {children}
      {trailingIcon ? <span className="inline-flex size-[var(--component-icon-size-md)] shrink-0 [&>svg]:size-full">{trailingIcon}</span> : null}
    </button>
  )
)
Button.displayName = "Button"
